const ORDERS = /\/rest\/v1\/orders\?/;
const DELETE_RPC = /\/rest\/v1\/rpc\/delete_customer/;
const ITEM_DELETE = /^מחיקה/;
const CHECKING = 'בודק הזמנות…';
const LOAD_ERROR = 'ההזמנות לא נטענו, רענן ונסה שוב';
const KEEP_HISTORY = 'יישמר בהיסטוריה';
const ARCHIVE_TEXT = /תישמר בהיסטוריה|יישמרו בהיסטוריה/;
const NO_ORDERS = 'ללקוח אין הזמנות';
const FOREVER = 'לצמיתות';
const DEBT_PREFIX = 'שים לב: ללקוח יתרת חוב פתוחה של';
const MONEY = /₪[\d,]+\.\d{2}/;
const PRODUCT = 'מצית קליפט';

type DelFrame = { t: number; dialog: string; item: string };

// ── наблюдатель кадров окна удаления и пункта «מחיקה» (в странице) ────────────────────────
function delObserver() {
  const w = window as unknown as { __qaDel?: DelFrame[] };
  if (w.__qaDel) return;
  w.__qaDel = [];
  const norm = (el: Element) => ((el as HTMLElement).innerText || '').replace(/\s+/g, ' ').trim();
  let last = '';
  const rec = () => {
    try {
      const dialog = [...document.querySelectorAll('[role=dialog],[role=alertdialog]')].map(norm).join(' | ');
      const item = [...document.querySelectorAll('[role=menuitem]')].map(norm).filter((s) => s.startsWith('מחיקה')).join(' | ');
      const k = `${dialog}§${item}`;
      if (k !== last) { last = k; w.__qaDel!.push({ t: Math.round(performance.now()), dialog, item }); }
    } catch { /* кадр без body */ }
  };
  const start = () => { new MutationObserver(rec).observe(document, { subtree: true, childList: true, characterData: true, attributes: true }); rec(); };
  if (document.documentElement) start(); else document.addEventListener('readystatechange', start, { once: true });
}

const frames = (page: Page) => page.evaluate(() => (window as unknown as { __qaDel: DelFrame[] }).__qaDel || []);

/** Держит GET orders до release(); release() возвращает число кадров, записанных ДО отпускания, и ждёт ответ. */
async function hold(page: Page, url: RegExp) {
  let open!: () => void;
  const gate = new Promise<void>((r) => (open = r));
  let gotFirst!: () => void;
  const first = new Promise<void>((r) => (gotFirst = r));
  let released = false;
  await page.route(url, async (route) => {
    if (route.request().method() === 'GET' && !released) { gotFirst(); await gate; }
    await route.fallback().catch(() => { /* страница закрыта */ });
  });
  return {
    first,
    async release() {
      const mark = (await frames(page)).length;
      const resp = page.waitForResponse((r) => url.test(r.url()) && r.request().method() === 'GET', { timeout: 30_000 });
      released = true;
      open();
      await resp;
      return mark;
    },
  };
}

/** Ответ GET orders (регистрировать ДО перехода). */
const ordersLoaded = (page: Page) =>
  page.waitForResponse((r) => ORDERS.test(r.url()) && r.request().method() === 'GET' && r.ok(), { timeout: 30_000 });

const deleteItem = (page: Page) => page.getByRole('menuitem', { name: ITEM_DELETE });
const deleteDialog = (page: Page) => page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: 'מחיקת לקוח' }) });

async function openMenu(page: Page, row: Locator) {
  await row.getByRole('button', { name: 'פעולות' }).click();
  await expect(page.getByRole('menuitem', { name: 'כרטיס לקוח' })).toBeVisible();
}

async function closeMenu(page: Page) {
  if (await page.getByRole('menuitem', { name: 'כרטיס לקוח' }).count()) await page.keyboard.press('Escape');
  await expect(page.getByRole('menuitem', { name: 'כרטיס לקוח' })).toHaveCount(0);
}

async function waitListShell(page: Page) {
  await expect(page.getByRole('heading', { level: 1, name: 'לקוחות' })).toBeVisible({ timeout: 30_000 });
}

const flat = async (l: Locator) => (await l.innerText()).replace(/\s+/g, ' ').trim();

/** outcome из ответа rpc delete_customer (объект, массив или строка). */
function outcomeOf(json: unknown): string | undefined {
  const o = Array.isArray(json) ? json[0] : json;
  if (typeof o === 'string') return o;
  return (o as { outcome?: string } | null)?.outcome;
}

