    await expect(item, '«מחיקה» при ошибке orders — неактивна').toBeDisabled();
    await expect(item).toContainText(LOAD_ERROR);
    await expect(item).not.toContainText(KEEP_HISTORY);
    await item.click({ force: true });
    await expect(deleteDialog(page), 'окно не открылось').toHaveCount(0);
    await closeMenu(page);

    const log = await frames(page);
    expect(log.filter((f) => f.dialog).map((f) => `${f.t}ms ${f.dialog.slice(0, 80)}`), 'окно удаления ни в одном кадре').toEqual([]);
