// ── QA-AUTO: сервер решает deleted / archived (@data, serial) ────────────────────────────────
const TS = Date.now().toString().slice(-7);
const NAME_A = `QA-AUTO-7f32dc-${TS}-A`; // без заказов → deleted
const NAME_B = `QA-AUTO-7f32dc-${TS}-B`; // все заказы «נדחתה» → archived (через UI)
const NAME_C = `QA-AUTO-7f32dc-${TS}-C`; // заказ «ממתינה לאישור», прямой rpc при незагруженных orders → archived

type Order = { no: string; url: string };
const created: { name: string; id: string; order?: Order }[] = [];

async function adminPage(browser: Browser, baseURL: string | undefined) {
  const ctx = await browser.newContext({ storageState: authFile('admin'), baseURL, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
  return { ctx, page: await ctx.newPage() };
}

/** Клиент без ссылки (переключатель выкл.) → id. */
async function createCustomer(page: Page, name: string) {
  await openList(page);
  const dlg = await openNewCustomer(page);
  const sw = dlg.getByRole('switch', { name: SWITCH_LINK });
  await sw.click();
  await expect(sw).toHaveAttribute('aria-checked', 'false');
  await dlg.getByRole('textbox', { name: /^שם העסק/ }).fill(name);
  const [resp] = await Promise.all([
    page.waitForResponse((r) => /\/rest\/v1\/customers(\?|$)/.test(r.url()) && r.request().method() === 'POST'),
    dlg.getByRole('button', { name: BTN_SAVE }).click(),
  ]);
  expect(resp.status(), `POST customers «${name}»`).toBe(201);
  await expect(page.getByRole('dialog')).toHaveCount(0, { timeout: 15_000 });
  const body = await resp.json();
  const id = (Array.isArray(body) ? body[0] : body).id as string;
  created.push({ name, id });
  test.info().annotations.push({ type: 'test-data', description: `клиент ${name} (${id})` });
  return id;
}

/** id товара из /catalog, без изменений. */
async function productId(page: Page, name: string) {
  await page.goto('/catalog');
  await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(name);
  await expect(page.getByRole('button', { name: `קליטת מלאי — ${name}`, exact: true })).toBeVisible({ timeout: 20_000 });
  await page.getByRole('button', { name, exact: true }).first().click();
  await expect(page).toHaveURL(/\/catalog\/[0-9a-f-]{36}\/edit$/, { timeout: 20_000 });
  const id = page.url().match(/\/catalog\/([0-9a-f-]{36})\/edit$/)![1];
  await page.getByRole('button', { name: 'ביטול', exact: true }).click();
  return id;
}

/** «הזמנה מהודעה» для клиента (распознавание подменено: 1 × «מצית קליפט») → «ממתינה לאישור». */
async function createOrder(page: Page, customer: string) {
  const pid = await productId(page, PRODUCT);
  const ai = await mockAi(page, 'order-photo', 200, { ok: true, lines: [{ text: `1 ${PRODUCT}`, product_id: pid, qty: 1 }] });
  await page.goto('/orders/new');
  await expect(page.getByRole('heading', { level: 1, name: 'הזמנה מהודעה' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('combobox').fill(customer);
  await page.getByRole('option').filter({ has: page.getByText(customer, { exact: true }) }).first().click();
  await page.getByRole('textbox', { name: 'הודעת ההזמנה' }).fill(`1 ${PRODUCT}`);
  await page.getByRole('button', { name: 'קריאת הודעה' }).click();
  await expect(page.getByRole('button', { name: `הסרת שורה — ${PRODUCT}`, exact: true })).toBeVisible({ timeout: 20_000 });
  await page.getByRole('textbox', { name: /הערה להזמנה/ }).fill(`${customer} #7f32dc`);
  const save = page.getByRole('button', { name: /^רישום ההזמנה/ });
  await expect(save).toBeEnabled({ timeout: 20_000 });
  const [resp] = await Promise.all([
    page.waitForResponse((r) => r.url().includes('/rpc/create_customer_order'), { timeout: 30_000 }),
    save.click(),
  ]);
  expect(resp.status(), 'create_customer_order').toBeLessThan(300);
  await page.waitForURL(/\/orders\/[0-9a-f-]{36}$/, { timeout: 30_000 });
  const h1 = page.getByRole('heading', { level: 1, name: /^הזמנה #\d+$/ });
  await expect(h1).toBeVisible({ timeout: 30_000 });
  const no = (await h1.innerText()).match(/#(\d+)/)![1];
  expect(ai.hits, 'распознавание — один подменённый вызов').toBe(1);
  const order = { no, url: page.url() };
  const c = created.find((x) => x.name === customer);
  if (c) c.order = order;
  test.info().annotations.push({ type: 'test-data', description: `заказ #${no} (${customer}, ${PRODUCT} ×1, ₪5) — неудаляем` });
  return order;
}

const orderHeader = (page: Page) => page.getByRole('heading', { level: 1 }).locator('..');

async function rejectOrder(page: Page, o: Order) {
  await page.goto(o.url);
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${o.no}` })).toBeVisible({ timeout: 30_000 });
  if (!(await page.getByRole('button', { name: 'דחייה', exact: true }).count())) return;
  await page.getByRole('button', { name: 'דחייה', exact: true }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: `דחיית הזמנה #${o.no}` })).toBeVisible();
  await dlg.getByRole('textbox', { name: 'סיבת הדחייה *' }).fill('QA-AUTO 7f32dc');
  await dlg.getByRole('button', { name: 'דחה הזמנה' }).click();
  await expect(orderHeader(page)).toContainText('נדחתה', { timeout: 20_000 });
}

/** Список после ответа orders, строка клиента. */
async function rowReady(page: Page, name: string) {
  const ord = ordersLoaded(page);
  await openList(page);
  await ord;
  await search(page, name);
  const row = rowOf(page, name);
  await expect(row).toBeVisible({ timeout: 20_000 });
  return row;
}

/** Подтвердить удаление в окне; проверить тело (только p_id) и вернуть outcome. */
async function confirmDelete(page: Page, id: string) {
  const dlg = deleteDialog(page);
  const [resp] = await Promise.all([
    page.waitForResponse((r) => DELETE_RPC.test(r.url()) && r.request().method() === 'POST', { timeout: 30_000 }),
    dlg.getByRole('button', { name: ITEM_DELETE }).click(),
  ]);
  const body = JSON.parse(resp.request().postData() || '{}');
  expect(Object.keys(body), 'тело rpc delete_customer — только p_id (режим не задаётся экраном)').toEqual(['p_id']);
  expect(body.p_id).toBe(id);
  expect(resp.ok(), `rpc delete_customer → ${resp.status()}`).toBe(true);
  return outcomeOf(await resp.json());
}

async function expectArchived(page: Page, id: string, name: string) {
  const c = await rest(page, 'GET', `customers?select=id,archived_at&id=eq.${id}`);
  expect(c.json, `клиент ${name} не удалён навсегда (строка есть)`).toHaveLength(1);
  expect(c.json[0].archived_at, `${name}: archived_at задан`).toBeTruthy();
  const o = await rest(page, 'GET', `orders?select=id&customer_id=eq.${id}`);
  expect((o.json || []).length, `${name}: заказы на месте`).toBeGreaterThan(0);
}

test.describe('customers — שרת מחליט: נמחק לצמיתות / נשמר בהיסטוריה (#7f32dc)', () => {
  test.describe.configure({ mode: 'serial' });

  test.afterAll(async ({ browser }, testInfo) => {
    test.setTimeout(180_000);
    const { ctx, page } = await adminPage(browser, testInfo.project.use.baseURL);
    try {
      await openList(page);
      for (const c of created) {
        // заказ, оставшийся «ממתינה לאישור», — отклонить
        if (c.order) await rejectOrder(page, c.order).catch(() => { /* уже отклонён */ });
        if (!page.url().includes('/customers')) await openList(page);
        const r = await rest(page, 'GET', `customers?select=id,archived_at&id=eq.${c.id}`);
        if (Array.isArray(r.json) && r.json.length && !r.json[0].archived_at) {
          const d = await rest(page, 'POST', 'rpc/delete_customer', { p_id: c.id }); // без заказов — удалится, с заказами — архив
          expect(d.status, `уборка ${c.name}: rpc delete_customer`).toBeLessThan(300);
        }
      }
    } finally {
      await ctx.close();
    }
  });

  test('לקוח בלי הזמנות: החלון «ללקוח אין הזמנות… יימחק לצמיתות» בלי אזהרת חוב; גוף הבקשה רק p_id; outcome deleted; השורה נעלמה #7f32dc @desktop @data', async ({ page }) => {
    test.setTimeout(120_000);
    const id = await createCustomer(page, NAME_A);
    const row = await rowReady(page, NAME_A);

    await openMenu(page, row);
    const item = deleteItem(page);
    await expect(item).toBeEnabled();
    await expect(item).not.toContainText(KEEP_HISTORY);
    await item.click();
    const dlg = deleteDialog(page);
    await expect(dlg).toBeVisible();
    await expect(dlg).toContainText(NO_ORDERS);
    await expect(dlg).toContainText(FOREVER);
    await expect(dlg).not.toContainText(DEBT_PREFIX);
    await expect(dlg).not.toContainText(ARCHIVE_TEXT);

    expect(await confirmDelete(page, id), 'сервер: outcome deleted').toBe('deleted');
    await expect(row).toHaveCount(0, { timeout: 20_000 });
    const left = await rest(page, 'GET', `customers?select=id&id=eq.${id}`);
    expect(left.json, `${NAME_A} удалён навсегда`).toEqual([]);
  });

  test('כל ההזמנות «נדחתה»: ⋮ «יישמר בהיסטוריה», החלון «…תישמר בהיסטוריה» בלי «לצמיתות»; outcome archived; ההזמנה נשארת #7f32dc @desktop @data', async ({ page }) => {
    test.setTimeout(240_000);
    const id = await createCustomer(page, NAME_B);
    const order = await createOrder(page, NAME_B);
    await rejectOrder(page, order);

    const row = await rowReady(page, NAME_B);
    await openMenu(page, row);
    const item = deleteItem(page);
    await expect(item).toBeEnabled();
    await expect(item, 'клиент с заказами (все «נדחתה») — «יישמר בהיסטוריה»').toContainText(KEEP_HISTORY);
    await item.click();
    const dlg = deleteDialog(page);
    await expect(dlg).toBeVisible();
    await expect(dlg, 'текст архивации').toContainText(ARCHIVE_TEXT);
    await expect(dlg).not.toContainText(FOREVER);
    await expect(dlg).not.toContainText(NO_ORDERS);

    expect(await confirmDelete(page, id), 'сервер: outcome archived').toBe('archived');
    await expect(row).toHaveCount(0, { timeout: 20_000 });
    await expectArchived(page, id, NAME_B);

    await page.goto(order.url); // заказ виден в «הזמנות»
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${order.no}` })).toBeVisible({ timeout: 30_000 });
    await expect(orderHeader(page)).toContainText('נדחתה');
  });

  test('הזמנה «ממתינה לאישור» ו-orders עוד לא נטען: קריאה ישירה ל-rpc delete_customer {p_id} → archived, הלקוח לא נמחק לצמיתות #7f32dc @desktop @data', async ({ page }) => {
    test.setTimeout(240_000);
    const id = await createCustomer(page, NAME_C);
    await createOrder(page, NAME_C);

    const ord = await hold(page, ORDERS);
    await page.goto('/customers');
    await ord.first;
    await waitListShell(page);
    await search(page, NAME_C);
    const row = rowOf(page, NAME_C);
    await expect(row).toBeVisible({ timeout: 30_000 });
    await openMenu(page, row);
    await expect(deleteItem(page), 'экран ещё не знает заказы — «מחיקה» неактивна').toBeDisabled();
    await closeMenu(page);

    const d = await rest(page, 'POST', 'rpc/delete_customer', { p_id: id }); // orders на экране всё ещё задержан
    expect(d.status, `rpc delete_customer → ${d.status}`).toBeLessThan(300);
    expect(outcomeOf(d.json), `сервер решил по своим данным: ${JSON.stringify(d.json)}`).toBe('archived');
    await ord.release();
    await expectArchived(page, id, NAME_C);
  });
});
